def second_largest(xs: list[int]) -> int:
    """The second largest DISTINCT value. Assumes at least two distinct values."""
    distinct_values = set(xs)
    if len(distinct_values) < 2:
        raise ValueError("List must contain at least two distinct values")
    return sorted(distinct_values, reverse=True)[1]

def gcd(a: int, b: int) -> int:
    """Greatest common divisor of two non-negative integers, not both zero."""
    while b:
        a, b = b, a % b
    return a

