def word_count(s: str) -> dict[str, int]:
    """Count lowercase words split on whitespace."""
    words = s.lower().split()
    word_counts = {}
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1
    return word_counts
